/* cppi::748b5101d5381cdde772da5c3f951829a60955915bb733b84d6319286c4d4b41 */
select business_date as date_, security_id, 'MS757951' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-06' and business_date <= date '2025-06-10' and weight_ndo>0 and id_cppib_index = 'MS757951_GR_USD_0_0' and security_id is not null

/* cppi::b525f3109537641f37a5514d7cd729d7ba935c98312abe7f145028e201134cc7 */
select * from finance_accounting.model_portfolios where
business_date = date'2025-06-10'

/* cppi::91e53c7e9a6e37da07177928882ea7525656ed06c4addafc402e22542dae21cd */
select business_date as date_, security_id, 'SP500_25' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-10' and business_date <= date '2025-06-10' and weight_ndo>0 and id_cppib_index = 'SP500_25_GR_USD_0_0' and security_id is not null

