XCH_CD, s.market_status_code AS MARKET_STATUS, s.bloomberg_primary_listing_exchange_flag AS PRIMARY_FLG, sk.bloomberg_company_id AS ID_BB_COMPANY, sk.id_bb_parent_co AS ID_BB_PARENT_CO, s.listing_country_code AS COUNTRY_TRADE, s.round_lot_size AS ROUND_LOT_SIZE, 0 AS QUOTE_LOT_SIZE, s.underlying_instrument_cppib_sec_id AS UNDL_ID_CPPIBSEC, siun.sedol AS UNDL_SEDOL, ij.country_name AS CNTRY_NM, s.issue_country_iso AS ISSUE_CNTRY, 0 AS SHR_TOT_OUT, s.shares_outstanding_real / 1000000 AS SHR_OUT_TOT_MULT_SH FROM asset.asset_warrants_universe s LEFT JOIN reference.reference_country_codes ij ON ij.country_code = s.country_code LEFT JOIN asset.asset_security_identifiers_universe si ON si.cppib_sec_id = s.cppib_sec_id LEFT JOIN asset.asset_security_identifiers_universe siun ON siun.cppib_sec_id = s.underlying_instrument_cppib_sec_id LEFT JOIN party_details sk ON sk.cppib_party_id = s.cppib_underlyier_party_id LEFT JOIN gics_details gics ON gics.cppib_party_id = s.cppib_underlyier_party_id WHERE s.source_security_type_2 IN ('Right') AND s.delete_date IS NULL UNION ALL SELECT s.cppib_sec_id, s.business_date, s.cppib_party_id, s.country_code, si.domicile_cntry, si.incorp_country_code, s.currency_code, s.market_sector_description, s.source_security_type, s.source_security_type_2, s.instrument_description, s.instrument_name, si.bloomberg_security_id, s.bloomberg_unique_id, COALESCE(si.cusip, si.cins), si.sedol, si.isin, si.ticker, 0, 0, 0, sk.party_name, gics.sector_cd, gics.sector_nm, gics.indusgrp_cd, gics.indusgrp_nm, gics.indus_cd, gics.indus_nm, gics.subindus_cd, gics.subindus_nm, s.bloomberg_ticker_and_exchange, s.market_status_code, s.bloomberg_primary_listing_exchange_flag, sk.bloomberg_company_id, sk.id_bb_parent_co, s.listing_country_code, 0, 0, s.underlying_instrument_cppib_sec_id, NULL, ij.country_name, s.issue_country_iso, 0, s.shares_outstanding_real / 1000000 FROM asset.asset_futures_universe s LEFT JOIN reference.reference_country_codes ij ON ij.country_code = s.country_code LEFT JOIN asset.asset_security_identifiers_universe si ON si.cppib_sec_id = s.cppib_sec_id LEFT JOIN party_details sk ON sk.cppib_party_id = s.cppib_party_id LEFT JOIN gics_details gics ON gics.cppib_party_id = s.cppib_party_id WHERE s.source_security_type_2 IN ('Future', 'FUTURE') AND s.delete_reason IS NULL UNION ALL SELECT s.cppib_sec_id, s.business_date, s.cppib_party_id, s.country_code, si.domicile_cntry, si.incorp_country_code, s.currency_code, s.market_sector_description, s.source_security_type, s.source_security_type_2, s.instrument_description, s.instrument_name, si.bloomberg_security_id, s.bloomberg_unique_id, COALESCE(si.cusip, si.cins), si.sedol, si.isin, si.ticker, s.free_float_pct, 0, s.shares_outstanding_real, sk.party_name, gics.sector_cd, gics.sector_nm, gics.indusgrp_cd, gics.indusgrp_nm, gics.indus_cd, gics.indus_nm, gics.subindus_cd, gics.subindus_nm, s.bloomberg_ticker_and_exchange, s.market_status_code, s.bloomberg_primary_listing_exchange_flag, sk.bloomberg_company_id, sk.id_bb_parent_co, s.listing_country_code, s.round_lot_size, s.quote_lot_size, s.underlying_instrument_cppib_sec_id, siun.sedol, ij.country_name, s.issue_country_iso, 0, s.total_shares_out_multiple FROM asset.asset_equity_universe s JOIN reference.reference_exchange_codes_map recm ON recm.exchange_code = s.bloomberg_exchange AND recm.product_code = 'Equity' AND recm.composite_name <> '' LEFT JOIN reference.reference_country_codes ij ON ij.country_code = s.country_code LEFT JOIN asset.asset_security_identifiers_universe si ON si.cppib_sec_id = s.cppib_sec_id LEFT JOIN asset.asset_security_identifiers_universe siun ON siun.cppib_sec_id = s.underlying_instrument_cppib_sec_id LEFT JOIN party_details sk ON sk.cppib_party_id = s.cppib_party_id LEFT JOIN gics_details gics ON gics.cppib_party_id = s.cppib_party_id WHERE s.source_security_type_2 IN ('Common Stock', 'Depositary Receipt', 'Unit', 'Mutual Fund', 'REIT', 'Preference', 'Partnership Shares') AND s.bloomberg_ticker_and_exchange IS NOT NULL AND s.delete_date IS NULL), ranked_data AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY ID_CPPIBSEC, ID_CUSIP, ID_SEDOL, ID_ISIN, ID_TICKER ORDER BY BUSINESS_DT DESC) AS rn FROM combined_assets) SELECT * FROM ranked_data WHERE rn = 1 ORDER BY "ID_CPPIBSEC"
